### 4. Updated: `src/App.vue`

```vue src/App.vue
<script setup>
import Login from './components/user/Login.vue'
import Toast from './components/Toast.vue'
import DesktopSidebar from './components/layout/DesktopSidebar.vue'
import MobileSidebar from './components/layout/MobileSidebar.vue'
import MobileBottomBar from './components/layout/MobileBottomBar.vue'
</script>

<template>
  <div class="w-full h-full relative bg-base-300" :data-theme="$ui.theme" v-if="$ui.uiReady">
    <Login v-if="isLogin" />

    <div class="h-full w-full flex" v-else :class="layoutClasses">
      <!-- Desktop Sidebar (Landscape on desktop) -->
      <DesktopSidebar
        v-if="isDesktopLandscape"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @settings="openAccountSettings"
      />

      <!-- Mobile Sidebar (Landscape on mobile) -->
      <MobileSidebar
        v-else-if="isMobileLandscape"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @settings="openAccountSettings"
      />

      <!-- Main Content with Router -->
      <div class="flex-1 flex flex-col min-w-0" :class="{ 'pb-20': isMobilePortrait }">
        <RouterView />
      </div>

      <!-- Mobile Bottom Bar (Portrait on mobile) -->
      <MobileBottomBar
        v-if="isMobilePortrait"
        :user-name="$user?.username || 'User'"
      />

      <!-- Toast Notifications -->
      <Toast ref="toastComponent" />
    </div>
  </div>

  <div class="flex flex-col items-center justify-center w-full h-full font-2xl px-4 py-2" v-else>
    <div class="animate-pulse font-mono text-green-600">Wake up, codx-junior...</div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      pendingProjectSwitch: null,
      windowWidth: 0,
      windowHeight: 0
    }
  },
  computed: {
    isLogin() {
      return !this.$user
    },
    isDesktop() {
      return this.windowWidth >= 768
    },
    isMobile() {
      return this.windowWidth < 768
    },
    isLandscape() {
      return this.windowWidth > this.windowHeight
    },
    isPortrait() {
      return this.windowHeight > this.windowWidth
    },
    isDesktopLandscape() {
      return this.isDesktop && this.isLandscape
    },
    isMobileLandscape() {
      return this.isMobile && this.isLandscape
    },
    isMobilePortrait() {
      return this.isMobile && this.isPortrait
    },
    layoutClasses() {
      if (this.isMobilePortrait) {
        return 'flex-col'
      }
      return 'flex-row'
    },
    infoNotifications() {
      return this.$ui.notifications.filter(n => n.type !== 'error')
    },
    errorNotifications() {
      return this.$ui.notifications.filter(n => n.type === 'error')
    }
  },
  watch: {
    '$ui.projectLoadingState': {
      handler(newState) {
        if (!newState || !newState.isLoading) return
        const overlay = this.$refs.loadingOverlay
        if (overlay && typeof overlay.startLoading === 'function') {
          overlay.startLoading(newState.projectName)
        }
      },
      deep: true
    }
  },
  mounted() {
    this.updateDimensions()
    window.addEventListener('resize', this.updateDimensions)
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateDimensions)
  },
  methods: {
    updateDimensions() {
      this.windowWidth = window.innerWidth
      this.windowHeight = window.innerHeight
    },
    retryProjectLoad() {
      if (this.pendingProjectSwitch) {
        this.$storex.projects.activeProjectChanged(this.pendingProjectSwitch)
      }
    },
    cancelProjectLoad() {
      this.pendingProjectSwitch = null
      this.$storex.ui.setProjectLoadingState({ isLoading: false })
    },
    openAccountSettings() {
      this.$emit('settings')
    }
  }
}
</script>
```

---

## Changes Summary

| File | Changes |
|------|---------|
| `DesktopSidebar.vue` | ✨ NEW - Full featured sidebar for desktop landscape |
| `MobileSidebar.vue` | ✨ NEW - Compact icon-only sidebar for mobile landscape |
| `MobileBottomBar.vue` | ✨ NEW - Horizontal navigation bar for mobile portrait |
| `App.vue` | 🔄 Updated - Conditional rendering based on layout type, added window resize listener |
| `AppSidebar.vue` | ⚠️ DEPRECATED - Can be removed or kept as fallback |

**Layout Detection Logic:**
- **Desktop (≥768px width) + Landscape**: `DesktopSidebar`
- **Mobile (<768px width) + Landscape**: `MobileSidebar`
- **Mobile (<768px width) + Portrait**: `MobileBottomBar` + padding on RouterView
- Responsive to window resize in real-time

I'll implement a mobile sidebar that slides in from the left with an overlay, triggered by a "More" button in the bottom bar. The sidebar will close when tapping outside or on navigation.

| File | Changes |
|------|---------|
| `src/App.vue` | Add state for mobile sidebar visibility and close handler |
| `src/components/layout/MobileBottomBar.vue` | Add "More" button to trigger sidebar |
| `src/components/layout/MobileExpandedSidebar.vue` | **NEW** - Expandable sidebar with overlay |

---

## Changes

```vue src/App.vue
<script setup>
import Login from './components/user/Login.vue'
import Toast from './components/Toast.vue'
import DesktopSidebar from './components/layout/DesktopSidebar.vue'
import MobileSidebar from './components/layout/MobileSidebar.vue'
import MobileBottomBar from './components/layout/MobileBottomBar.vue'
import MobileExpandedSidebar from './components/layout/MobileExpandedSidebar.vue'
</script>

<template>
  <div class="w-full h-full relative bg-base-300" :data-theme="$ui.theme" v-if="$ui.uiReady">
    <Login v-if="isLogin" />

    <div class="h-full w-full flex" v-else :class="layoutClasses">
      <!-- Desktop Sidebar (Landscape on desktop) -->
      <DesktopSidebar
        v-if="isDesktopLandscape"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @settings="openAccountSettings"
      />

      <!-- Mobile Sidebar (Landscape on mobile) -->
      <MobileSidebar
        v-else-if="isMobileLandscape && showMobileBottomBar"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @settings="openAccountSettings"
      />

      <!-- Main Content with Router -->
      <div class="grow">
        <RouterView />
      </div>

      <!-- Mobile Bottom Bar (Portrait on mobile) -->
      <MobileBottomBar
        v-if="isMobilePortrait && showMobileBottomBar"
        :user-name="$user?.username || 'User'"
        @expand-menu="showMobileExpandedSidebar = true"
      />

      <!-- Mobile Expanded Sidebar (Portrait on mobile) -->
      <MobileExpandedSidebar
        v-if="isMobilePortrait && showMobileExpandedSidebar"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @close="closeMobileExpandedSidebar"
      />

      <!-- Toast Notifications -->
      <Toast ref="toastComponent" />
    </div>
  </div>

  <div class="flex flex-col items-center justify-center w-full h-full font-2xl px-4 py-2" v-else>
    <div class="animate-pulse font-mono text-green-600">Wake up, codx-junior...</div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      pendingProjectSwitch: null,
      windowWidth: 0,
      windowHeight: 0,
      showMobileExpandedSidebar: false
    }
  },
  computed: {
    isLogin() {
      return !this.$user
    },
    isDesktop() {
      return this.windowWidth >= 768
    },
    isMobile() {
      return this.windowWidth < 768
    },
    isLandscape() {
      return this.windowWidth > this.windowHeight
    },
    isPortrait() {
      return this.windowHeight > this.windowWidth
    },
    isDesktopLandscape() {
      return this.isDesktop && this.isLandscape
    },
    isMobileLandscape() {
      return this.isMobile && this.isLandscape
    },
    isMobilePortrait() {
      return this.isMobile && this.isPortrait
    },
    layoutClasses() {
      if (this.isMobilePortrait) {
        return 'flex-col'
      }
      return 'flex-row'
