export default function Navigate({ $router, $storex }) {

  const routes = { 
    kanban: {
      board({ project: { project_name }, board }) {
        return `/${project_name}/kanban/${board}`
      }
    }
  }

  function getArgs(func) { 
    return function(args) {
      const newArgs = { ...args, project: args.project || $storex.projects.activeProject }
      return func.call(this, newArgs)
    }
  }

  let historyRegistered = false

  const $navigator = {
    get activeProject() {
      return $storex.projects.activeProject
    },
    init() {
      // 1. Check if this is the first page in the tab's session history
      if (window.history.length === 1) {

        // 2. Replace the current history entry with the root URL
        window.history.replaceState(null, '', '/');

        // 3. Push the current page on top of the root URL
        window.history.pushState(null, '', window.location.href);
      }
    },
    async onRouteChanged({ from, to }) {

      // ── OAuth callback ──────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return '/'
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return '/'
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return '/'
        }
      }

      // ── Standalone routes has name (opt-out of mobile/desktop redirect) ─────
      if (!!to.name) {
        return true
      }

      // ── Mobile redirect ─────────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ───────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { name: 'home', replace: true }
      }

      return true
    },
    kanban: {
      board: getArgs(async function(args) {
        const { project, board } = args
        if (project !== $navigator.activeProject) {
          await $storex.projects.activeProjectChanged(project)
        }
        $storex.projects.setActiveBoard(board)
        $storex.ui.showTab('tasks')
        $router.push(routes.kanban.board(args))
      })
    },
    workspace: {
      navigateTo(workspaceId, workspaceName) {
        const isDesktopMode = $storex.ui.isDesktopMode
        const currentPath = $router.currentRoute.value.path

        if (isDesktopMode) {
          $router.push(`/workspace/${workspaceId}/${workspaceName}`)
        } else {
          // Quick chat mode
          const newPath = this.appendOrUpdateWorkspace(currentPath, workspaceId, workspaceName)
          $router.push(newPath)
        }
      },
      appendOrUpdateWorkspace(currentPath, workspaceId, workspaceName) {
        // Pattern: /chat/{chatId}/{chatName}
        // Target: /chat/{chatId}/{chatName}/workspace/{workspaceId}/{workspaceName}

        const chatMatch = currentPath.match(/^\/chat\/([^/]+)\/([^/]+)/)
        if (!chatMatch) {
          return currentPath
        }

        const [, chatId, chatName] = chatMatch
        const baseChat = `/chat/${chatId}/${chatName}`

        // Check if workspace already exists in path
        const hasWorkspace = currentPath.includes('/workspace/')

        if (hasWorkspace) {
          // Update existing workspace
          return currentPath.replace(
            /\/workspace\/[^/]+\/[^/]+/,
            `/workspace/${workspaceId}/${workspaceName}`
          )
        } else {
          // Append new workspace
          return `${baseChat}/workspace/${workspaceId}/${workspaceName}`
        }
      },
      getCurrentWorkspace() {
        const currentPath = $router.currentRoute.value.path
        const workspaceMatch = currentPath.match(/\/workspace\/([^/]+)\/([^/]+)/)

        if (workspaceMatch) {
          return {
            id: workspaceMatch[1],
            name: workspaceMatch[2]
          }
        }

        return null
      },
      hasWorkspaceContext() {
        return this.getCurrentWorkspace() !== null
      }
    }
  }
  return $navigator
}

import { v4 as uuidv4 } from 'uuid';
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

const EVENT_EXPIRE_SECONDS = 120
setInterval(() => $storex.session.tick(), 1000)

import { API } from '../api/api'

// ── HTTP interceptors ────────────────────────────────────────────────────────
API.interceptors = {
  request: [
    (config) => {
      $storex.session.incApiCalls()
      return config
    },
    (error) => {
      $storex.session.decApiCalls()
      return Promise.reject(error)
    }
  ],
  response: [
    (response) => {
      $storex.session.decApiCalls()
      return response
    },
    (error) => {
      $storex.session.decApiCalls()
      $storex.session.setLastError(error)
      console.error("API ERROR:", error)
      $storex.session.onError(error.toString())
    }
  ]
}

export const state = () => ({
  apiCalls: 0,
  lastError: null,
  id: uuidv4(),
  ts: new Date().getTime(),
  notifications: [],
  connected: false,
  user: {
    userName: new Date().getTime()
  },
  users: null,
  events: []
})

export const getters = getterTree(state, {
  lastEvent: state => state.events[state.events.length - 1],
  wikiEvents: ({ events }) => events.filter(e => e.data?.type === 'wiki'),
  socket: () => API.socket
})

export const mutations = mutationTree(state, {
  incApiCalls(state) {
    state.apiCalls = state.apiCalls + 1
  },
  decApiCalls(state) {
    state.apiCalls = state.apiCalls - 1
  },
  setLastError(state, error) {
    state.lastError = error
  },
  set$childCodxJuior(state, $childCodxJuior) {
    state.$childCodxJuior = $childCodxJuior
  },
  addNotification(_, notification) {
    $storex.ui.addNotification(notification)
  },
  setConnected(state, connected) {
    state.connected = connected
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init () {
      $storex.session.connect()
    },

    tick ({ state }) {
      const expireNotif = new Date( Date.now() - 1000 * EVENT_EXPIRE_SECONDS ).getTime()
      if (state.events.find(e => e.ts < expireNotif)) {
        state.events = state.events.filter(e => e.ts >= expireNotif)
      }
    },

    connect () {
      if (!API.user) {
        API.disconnectSocket()
        return
      }

      API.initSocket({
        onConnect(socketId) {
          console.log('[session] socket connected', socketId)
          $storex.session.setConnected(true)
          $storex.session.login()
        },
        onDisconnect() {
          console.log('[session] socket disconnected')
          $storex.session.setConnected(false)
        },
        onEvent(payload) {
          $storex.session.onEvent(payload)
        }
      })
    },

    login({ state }) {
      API.socket.emit('codx-junior-login', { user: API.user }, users => {
        state.users = users
      })
    },

    onEvent({ state }, { event, data }) {
      console.log("On server message", event, data)
      state.events.push({ event, data, ts: new Date().getTime() })
      const { codx_path, type, chat } = data
      if (codx_path) {
        data.project = $storex.projects.allProjects?.find(p => p.codx_path === codx_path)
      }
      if (chat) {
        $storex.chats.onChatEvent({ event, data })
      }
      if (type === 'notification') {
        $storex.ui.addNotification(data)
      }
      if (event === 'codx-junior-online-users') {
        $storex.users.setOnlineUsers(data.users)
      }
    },

    onInfo(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'info' })
    },
    onWarning(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'warning' })
    },
    onError(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'error' })
    },

    emit(_, { event, data }) {
      API.socket?.emit(event, data || {})
    }
  }
)

